(function(){window.addEventListener('cookieadmin_before_consent_display',function(){if(cookieadmin_pro_handle_gpc()){cookieadmin_policy.hide_banner=!0}})})()
function cookieadmin_pro_set_consent(prefrenc,days){if(cookieadmin_pro_vars&&cookieadmin_pro_vars.respect_gpc){if(!cookieadmin_pro_handle_set_gpc()){return!1}}
const data='action=cookieadmin_pro_ajax_handler&cookieadmin_act=save_consent'+'&cookieadmin_preference='+encodeURIComponent(JSON.stringify(Object.keys(prefrenc)));let payload=data;if(cookieadmin_is_obj(cookieadmin_is_consent)&&!!cookieadmin_is_consent.consent){payload+='&cookieadmin_consent_id='+cookieadmin_is_consent.consent}
const xhttp=new XMLHttpRequest();xhttp.open('POST',cookieadmin_pro_vars.ajax_url,!0);xhttp.setRequestHeader('Content-Type','application/x-www-form-urlencoded; charset=UTF-8');xhttp.onload=function(){if(this.status===200){try{const parsed=JSON.parse(this.responseText);if(parsed.success&&parsed.data&&parsed.data.response){cookieadmin_save_consent_cookie(prefrenc,days,parsed.data.response);if(cookieadmin_pro_vars&&cookieadmin_pro_vars.respect_gpc){var overrideEle=document.getElementById('cookieadmin_gpc_override');if(overrideEle){overrideEle.style.display='block'}}}}catch(e){console.error("Invalid JSON response:",e)}}};xhttp.onerror=function(){console.error("AJAX request failed")};xhttp.send(payload);return!0}
function cookieadmin_pro_handle_set_gpc(){var consentData=cookieadmin_is_cookie("cookieadmin_consent");if(consentData&&consentData.respect_gpc){var override=document.getElementById('cookieadmin-override_gpc');if(!override||!override.checked){alert(cookieadmin_pro_vars.gpc_alert?cookieadmin_pro_vars.gpc_alert:'Please accept override GPC before saving preference.');return!1}}
return!0}
function cookieadmin_pro_check_gpc(){if(!cookieadmin_pro_vars||!cookieadmin_pro_vars.respect_gpc){return!1}
if(typeof navigator!=='undefined'&&typeof navigator.globalPrivacyControl!=='undefined'){if(navigator.globalPrivacyControl===!0||navigator.globalPrivacyControl==='true'){return!0}}
if(cookieadmin_pro_vars&&cookieadmin_pro_vars.gpc_enabled){return!0}
return!1}
function cookieadmin_pro_handle_gpc(){if(!cookieadmin_pro_check_gpc()){return!1}
var overRideEle=document.getElementById('cookieadmin_gpc_override');var consentData=cookieadmin_is_cookie("cookieadmin_consent");if(overRideEle){overRideEle.style.display=(consentData&&consentData.respect_gpc===!0)?'':'none'}
if(consentData){return!1}
const gpc_preferences={'functional':!0,'respect_gpc':!0,};cookieadmin_pro_set_consent(gpc_preferences,365);cookieadmin_pro_show_gpc_message();return!0}
function cookieadmin_pro_show_gpc_message(){var toast=document.getElementById('cookieadmin-gpc-toast');if(!toast){return}
closeBtn=toast.querySelector('button');if(!closeBtn){return}
closeBtn.addEventListener('mouseenter',()=>closeBtn.style.opacity='1');closeBtn.addEventListener('mouseleave',()=>closeBtn.style.opacity='0.7');closeBtn.addEventListener('click',()=>{toast.style.opacity='0';toast.style.transform='translateY(20px)';toast.style.transition='opacity 0.3s ease, transform 0.3s ease, visibility 0s 0.3s';toast.style.visibility='hidden';setTimeout(()=>{if(document.body.contains(toast)){document.body.removeChild(toast)}},300)});requestAnimationFrame(()=>{toast.style.visibility='visible';toast.style.opacity='1';toast.style.transform='translateY(0)';toast.style.transition='opacity 0.3s ease, transform 0.3s ease, visibility 0s'});setTimeout(()=>{if(document.body.contains(toast)){toast.style.opacity='0';toast.style.transform='translateY(20px)';toast.style.transition='opacity 0.3s ease, transform 0.3s ease, visibility 0s 0.3s';toast.style.visibility='hidden';setTimeout(()=>{if(document.body.contains(toast)){document.body.removeChild(toast)}},300)}},10000)}